import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/en/whatsapp-detalhe.png",r="/pro-agent-hub-installer/capturas/en/msteams-detalhe.png",u=JSON.parse('{"title":"Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/integracoes.md","filePath":"en/interface/integracoes.md","lastUpdated":1787856241000}'),h={name:"en/interface/integracoes.md"};function i(p,e,c,l,d,g){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><p>They take an agent or a team to where people already talk, instead of asking them to come into the platform.</p><p>Both integrations work the same way: the platform exposes a <strong>webhook</strong>, the external service calls that address on every incoming message, the agent answers and the platform sends the reply back through the same channel.</p><p>In both, you link <strong>an agent or a team</strong> — never both.</p><h2 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h2><p><img src="'+n+'" alt="whatsapp-detalhe"></p><p>The connection goes through the <strong>Evolution API</strong>, which is what actually talks to WhatsApp. The record holds the server address, the API key and the instance name.</p><p>Once saved, copy the <strong>webhook address</strong> from the screen and configure it in the Evolution API. Without that step the integration sits there and never receives anything — it is the most common mistake.</p><p><strong>The webhook token is required.</strong> It is what tells a message from your Evolution API apart from any request that happens to find the address. With no token checked, the webhook would be an open door.</p><h3 id="two-options-that-change-the-behaviour" tabindex="-1">Two options that change the behaviour <a class="header-anchor" href="#two-options-that-change-the-behaviour" aria-label="Permalink to &quot;Two options that change the behaviour&quot;">​</a></h3><p><strong>Public mode.</strong> On, every message is handled as the platform&#39;s service user instead of creating one user per phone number. That is what you want for an open-to-the-public service desk; it is what you do <strong>not</strong> want when each person should have their own history.</p><p><strong>Reply with errors.</strong> On, a processing failure becomes a message back to whoever wrote. You can replace the raw exception text with your own — and you should: a technical error message in a customer&#39;s WhatsApp helps nobody.</p><h2 id="microsoft-teams" tabindex="-1">Microsoft Teams <a class="header-anchor" href="#microsoft-teams" aria-label="Permalink to &quot;Microsoft Teams&quot;">​</a></h2><p><img src="'+r+'" alt="msteams-detalhe"></p><p>The connection goes through a <strong>bot registered in Azure</strong>. The record holds the App ID, the bot password and, optionally, the tenant.</p><p>The path is the reverse of WhatsApp: first register the bot in Azure, then point its <em>messaging endpoint</em> at the webhook this screen shows.</p><p>Worth knowing before you start: registering the bot is done in the Azure portal, outside the platform, and usually depends on whoever administers the company&#39;s tenant. That is the slow part.</p>',17)])])}const w=t(h,[["render",i]]);export{u as __pageData,w as default};
